def comps(g):
    Y,X=g.shape; lab=-np.ones((Y,X),int); nid=[-1]*0
    n=0
    out=[]
    for r in range(Y):
        for c in range(X):
            v=int(g[r,c])
            idx=r*X+c
            if lab[idx]>=0: continue
            # flood fill
            stack=[idx]; size=0; pts=[]
            while stack:
                x,y=stack.pop(); size+=1; pts.append((x,y))
                if lab[idx]>0: pass
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<Y and 0<=ny<X and g[nx,ny]==v and lab[(nx)*X+(ny)]<0:
                            lab[nx*X+ny]=n; stack.append((nx,ny))
            for pt in pts: lab[pt[0]*X+pt[1]]=n
            n+=1
            out.append(n-1,pts)
    return out
