    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            idx=r*g.shape[1]+c
            if lab[idx]>=0: continue
            v=int(g[r,c]); stack=[(r,c)]; pts=[]; size=0; seen=set()
            while stack:
                x,y=stack.pop(); pts.append((x,y)); size+=1; seen.add((x,y))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<g.shape[0] and 0<=ny<g.shape[1] and g[nx,ny]==v and (nx,ny) not in seen:
                            stack.append((nx,ny))
            pts=list(seen)
            for p in pts: lab[p]=n
            n+=1
            out.append(pts)
    return out
