from collections import Counter
def regions(g,bg):
    seen=set(); R=[]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg or (r,c) in seen: continue
            color=g[r][c]; stack=[(r,c)]; cells=[]
            while stack:
                y,x=stack.pop()
                if (y,x) in seen: continue
                seen.add((y,x)); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not (ny,nx) in seen and g[ny][nx]==color: stack.append((ny,nx))
            R.append((color,cells))
    return R
